mapper.select:
select count(distinct u.user_id)
from (
    select ut.user_id, p.project_id
    from sys_project p, sys_user_team ut
    where p.team_id = ut.team_id and ut.team_lock != 1 and p.project_id = #{projectId}
    group by ut.user_id, p.project_id
) l1
left join sys_user_project l2 on l1.user_id = l2.user_id and l2.project_lock != 1 and l2.project_id = #{projectId}
left join sys_user u on u.user_id = l1.user_id

select distinct u.user_id, u.dept_id, u.user_name, u.nick_name, u.email, u.avatar, u.phonenumber, u.sex, u.status
from (
    select ut.user_id, p.project_id
    from sys_project p, sys_user_team ut
    where p.team_id = ut.team_id and ut.team_lock != 1 and p.project_id = #{projectId}
    group by ut.user_id, p.project_id
) l1
left join sys_user_project l2 on l1.user_id = l2.user_id and l2.project_lock != 1 and l2.project_id = #{projectId}
left join sys_user u on u.user_id = l1.user_id

order by u.user_id
limit #{limit} offset #{offset}

mapper.update:
update sys_user_project
project_lock = #{projectLock}, collect = #{collect},
where user_id = #{userId} and project_id = #{projectId}

mapper.select:
select user_project_id, user_id, project_id, collect, project_lock
from sys_user_project

    and user_id = #{userId}
    and project_id = #{projectId}
